 const original=await props();await tab.playwright.locator('#catalog-apply').click();expect((await tab.playwright.locator('#catalog-status').innerText()).includes('概算'),'Catalog applied without declared approximation');expect(JSON.stringify(await props())===JSON.stringify(original),'Refused catalog selection changed the material');await tab.playwright.locator('#catalog-isotropic').setChecked(true);await tab.playwright.locator('#catalog-poisson').fill('0.35');await tab.playwright.locator('#catalog-apply').click();const configured=await props();expect(configured.E===5999&&configured.nu===.35&&Number(configured.density)===1120&&configured.source.includes('rtpcompany.com'),'Published PP values or user assumption were not registered');const p=await project();expect(p.materialProperties.catalogSelection.poissonRatioOrigin==='user-assumption'&&p.materialProperties.catalogSelection.id==='rtp-105-cc','Catalog provenance missing from exported input');
 await tab.playwright.locator('#solve-run').click();await tab.playwright.locator('#status').filter({hasText:'解析が完了しました。'}).waitFor({state:'visible',timeoutMs:10000});expect((await tab.playwright.locator('#result-summary').innerText()).includes('100.000'),'PP result reaction missing');
 if(await tab.playwright.locator('#case-list article').count()>=8){const own=tab.playwright.locator('#case-list article').filter({hasText:'CUA Stokes reference'});expect(await own.count()===1,'No owned QA case available to free a slot');await own.getByRole('button',{name:'削除',exact:true}).click();}
 await tab.playwright.locator('#case-name').fill('CUA PP glass 30%');await tab.playwright.locator('#case-add').click();const saved=tab.playwright.locator('#case-list article').filter({hasText:'CUA PP glass 30%'});expect(await saved.count()===1,'PP catalog case save failed');
 if(!await tab.playwright.locator('#material-fields').evaluate(el=>el.parentElement.open))await tab.playwright.locator('summary').filter({hasText:'材料物性を入力'}).click();await tab.playwright.locator('#mat-youngModulus').fill('4000');await tab.playwright.locator('#material-save').click();const edited=await project();expect(edited.materialProperties.catalogSelection.overrides.youngModulus===4e9,'Manual modulus edit lost provenance or override');await saved.getByRole('button',{name:'保存結果を3D表示',exact:true}).click();expect((await props()).E===5999,'Saved catalog case did not restore original modulus');
 await tab.playwright.locator('#catalog-content').selectOption('');await tab.playwright.locator('#catalog-filler').selectOption('talc');await tab.playwright.locator('#catalog-family').selectOption('PE');expect(await tab.playwright.locator('#catalog-grade option').count()===4,'HDPE talc content variants missing');
 await tab.playwright.locator('#catalog-family').selectOption('ABS');expect(await tab.playwright.locator('#catalog-grade option').count()===1,'Commercial ABS talc reference missing');expect((await tab.playwright.locator('#catalog-detail').innerText()).includes('引張弾性率が未掲載'),'Unpublished ABS modulus was silently invented');await tab.playwright.locator('#catalog-experimental').setChecked(true);expect(await tab.playwright.locator('#catalog-grade option').count()===5,'Experimental ABS talc variants missing');await tab.playwright.locator('#catalog-grade').selectOption('sabic-patent-e3');await tab.playwright.locator('#catalog-isotropic').setChecked(true);await tab.playwright.locator('#catalog-apply').click();const experiment=await project();expect(experiment.materialProperties.catalogSelection.kind==='experimental'&&experiment.materialProperties.youngModulus===4.5e9&&experiment.materialProperties.density===null&&experiment.materialProperties.expansion===undefined,'Experimental reference was mislabeled or missing data invented');
